import{_ as a,o as e,c as i,a4 as l}from"./chunks/framework.BRzJ4ijD.js";const c=JSON.parse('{"title":"3. 形态演进: 大型机 → PC → 单片机/ARM → 云 → Web → AI → XPU","description":"","frontmatter":{},"headers":[],"relativePath":"prologue/mainframe-xpu.md","filePath":"prologue/mainframe-xpu.md","lastUpdated":1788475713000}'),r={name:"prologue/mainframe-xpu.md"};function n(o,t,s,d,h,p){return e(),i("div",null,[...t[0]||(t[0]=[l(`<h1 id="_3-形态演进-大型机-→-pc-→-单片机-arm-→-云-→-web-→-ai-→-xpu" tabindex="-1">3. 形态演进: 大型机 → PC → 单片机/ARM → 云 → Web → AI → XPU <a class="header-anchor" href="#_3-形态演进-大型机-→-pc-→-单片机-arm-→-云-→-web-→-ai-→-xpu" aria-label="Permalink to &quot;3. 形态演进: 大型机 → PC → 单片机/ARM → 云 → Web → AI → XPU&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>计算机 90 年史, 物理形态大致经过 <strong>7 段</strong> 演化. 每一段新形态不是上一段的&quot;放大版/缩小版&quot;, 而是<strong>新的契约 + 新的使用人群 + 新的工程师心智模型</strong>:</p><ol><li><strong>大型机 (mainframe)</strong>: 5 大单位共用 1 台机器, 分时.</li><li><strong>小型机 (minicomputer)</strong>: 实验室级, 关键用户开放.</li><li><strong>个人计算机 (PC)</strong>: 桌面 1 人 1 机.</li><li><strong>单片机 (MCU) / 嵌入式</strong>: 物联网之家家电、汽车、卡片电脑.</li><li><strong>ARM / 移动</strong>: 口袋超算, RISC 一夜成反主流. 同时云计算也起飞.</li><li><strong>Web / 云原生</strong>: 用户运行不再占设备, &quot;数据在云上, 浏览器即终端&quot;.</li><li><strong>AI / XPU</strong>: 数据中心向张量机倾斜, 在 N 年内 GPU / NPU + CPU 共生, 异构成为主流.</li></ol><p>每段不仅硬件变, 软件 / 用户 / 商业模式也变. 我们把&quot;形态学&quot;这一节当作&quot;硬件 + 软件 + 人的契约&quot; 三联一起讲.</p><p>读完应能: 给一台新设备 (e.g. Groq LPU / Apple Vision / 某家国产 7nm 服务器芯片) 立刻判断它在哪一段 / 在异构谱系哪一端 / 它依赖上一段哪些遗产.</p><hr><h2 id="一、形态演进总图" tabindex="-1">一、形态演进总图 <a class="header-anchor" href="#一、形态演进总图" aria-label="Permalink to &quot;一、形态演进总图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1960.DataBindings</span></span>
<span class="line"><span>┌──────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 1. Mainframe (IBM 360 / 370 / z)            单台 / 分时共享    │</span></span>
<span class="line"><span>│ 2. Mini (PDP-11 / VAX)                        实验室级          │</span></span>
<span class="line"><span>│ 3. PC (x86 / PC-clone)                     1 人 1 机, 平民化   │</span></span>
<span class="line"><span>│ 4. MCU / 嵌入式 (Arduino / Pi / 单片机)    几人franc块           │</span></span>
<span class="line"><span>│ 5. Mobile (ARM 手机 / 平板)                  口袋超算           │</span></span>
<span class="line"><span>│ 6. Cloud / Web (AWS / Azure / GCP)         1 服务 / N 用户      │</span></span>
<span class="line"><span>│ 7. AI / XPU (H100 / NPU / TPU / 量子预研)   分工化算力          │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────────────┘</span></span></code></pre></div><p>每一阶段, <strong>单台算力 + 人数 + 软件范式</strong> 这三条线互相带火. 表三条线随时间:</p><table tabindex="0"><thead><tr><th>阶段</th><th>代表硬件</th><th>算力 (相对)</th><th>用户数 (相对)</th><th>软件范式</th></tr></thead><tbody><tr><td>Mainframe</td><td>IBM 360/370</td><td>1 (基线)</td><td>共享 100 量级</td><td>批 / 分时, COBOL / Fortran, 卡片</td></tr><tr><td>Mini</td><td>PDP-11/VAX</td><td>0.3</td><td>1000+ (研究)</td><td>Multics, Unix 雏形, C</td></tr><tr><td>PC</td><td>x86 + DOS/Win</td><td>0.5-2</td><td>1 亿-10 亿</td><td>桌面 GUI, C++, JS</td></tr><tr><td>MCU</td><td>ATmega / stm32</td><td>10⁻³</td><td>─ (隐入背景)</td><td>baremetal / RTOS</td></tr><tr><td>Mobile</td><td>ARM64 SoC</td><td>1-5</td><td>60 亿 (手机)</td><td>App Store / 触屏</td></tr><tr><td>Cloud</td><td>x_a7 / Graviton</td><td>N × 大机架</td><td>数亿共享</td><td>容器 / IaC / 微服务</td></tr><tr><td>AI / XPU</td><td>H100 / B200 / TPU / NPU</td><td>N × GPU × 100</td><td>数百万开发者</td><td>框架 (PT/JAX) + Agent</td></tr></tbody></table><hr><h2 id="二、阶段-1-大型机-1965" tabindex="-1">二、阶段 1: 大型机 (1965-) <a class="header-anchor" href="#二、阶段-1-大型机-1965" aria-label="Permalink to &quot;二、阶段 1: 大型机 (1965-)&quot;">​</a></h2><h3 id="_2-1-物理形态" tabindex="-1">2.1 物理形态 <a class="header-anchor" href="#_2-1-物理形态" aria-label="Permalink to &quot;2.1 物理形态&quot;">​</a></h3><ul><li>一台 IBM S/360 = 几个机柜, 水冷, 卷磁带库, 集中管理. 当年 &quot;data processing department&quot;.</li><li>操作系统 OS/360 (later MVS / VM / z/OS); 任务, JCL (Job Control Language).</li><li>编程范式: COBOL (商业), FORTRAN (科学), PL/I (混合), 后来 RPG, 汇编.</li></ul><h3 id="_2-2-契约-不变式" tabindex="-1">2.2 契约 / 不变式 <a class="header-anchor" href="#_2-2-契约-不变式" aria-label="Permalink to &quot;2.2 契约 / 不变式&quot;">​</a></h3><ul><li><strong>批处理 + 分时 (TSO)</strong>: <ul><li>批: 提脚本 → 等结果. 用 JCL 描述作业调度.</li><li>分时: 写终端 (3270) 上 ISPF.</li></ul></li><li><strong>可靠为先</strong>: 7x24 不停. RAS (Reliability/Availability/Serviceability) 重于性能.</li></ul><h3 id="_2-3-至今大型机仍在使用" tabindex="-1">2.3 至今大型机仍在使用 <a class="header-anchor" href="#_2-3-至今大型机仍在使用" aria-label="Permalink to &quot;2.3 至今大型机仍在使用&quot;">​</a></h3><ul><li>IBM z15 / z16 用 5nm 工艺, 跑 z/OS, 在银行 / 航空 / 政府仍主力. 其工作负载大多是 COBOL 老 transaction 处理系统; 据估计全球 200K+ COBOL 程序员仍在岗.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>大型机最不常见的契约是 &quot;<strong>已知不停年数 70+</strong>&quot;. 把银行核心交易移到云或 Kubernetes 等价要重建这套 SLA 的工程量. 这就是为什么 80 年代预言&quot;大型机必死&quot;至今没兑现.</p></div><hr><h2 id="三、阶段-2-小型机-1965-1985" tabindex="-1">三、阶段 2: 小型机 (1965-1985) <a class="header-anchor" href="#三、阶段-2-小型机-1965-1985" aria-label="Permalink to &quot;三、阶段 2: 小型机 (1965-1985)&quot;">​</a></h2><h3 id="_3-1-pdp-vax" tabindex="-1">3.1 PDP/VAX <a class="header-anchor" href="#_3-1-pdp-vax" aria-label="Permalink to &quot;3.1 PDP/VAX&quot;">​</a></h3><ul><li><strong>DEC PDP-8</strong> (1965): 第一台 &lt; $20K 的小型机 → 大学实验室都能买.</li><li><strong>PDP-11</strong> (1970): 决定性影响, 给 Ken Thompson &amp; Dennis Ritchie 写 Unix 用. C 语言在此诞生.</li><li><strong>VAX-11/780</strong> (1977): 32 位, 单机虚拟内存, 标准 1 MIPS 性能基准.</li></ul><h3 id="_3-2-关键遗产" tabindex="-1">3.2 关键遗产 <a class="header-anchor" href="#_3-2-关键遗产" aria-label="Permalink to &quot;3.2 关键遗产&quot;">​</a></h3><ul><li><strong>Unix</strong> 与 <strong>C</strong> 都在 PDP 上诞生 → 第一份与硬件解耦的 OS + 语言 (1973 C 重写 Unix kernel). → 后续 Linux / BSD / Solaris 全都站着.</li><li><strong>分时系统 Unix</strong> 让程序员直接交互式开发, 不再写卡片等一天.</li></ul><h3 id="_3-3-1980-后逐渐让位-pc" tabindex="-1">3.3 1980 后逐渐让位 PC <a class="header-anchor" href="#_3-3-1980-后逐渐让位-pc" aria-label="Permalink to &quot;3.3 1980 后逐渐让位 PC&quot;">​</a></h3><ul><li>minicomputer 因 PC 在性能上赶上 (80486 一代) 而 vax 都被 Sun / SGI 工作站替代 → 进一步 PC / Linux 替代.</li></ul><hr><h2 id="四、阶段-3-个人计算机-1981" tabindex="-1">四、阶段 3: 个人计算机 (1981-) <a class="header-anchor" href="#四、阶段-3-个人计算机-1981" aria-label="Permalink to &quot;四、阶段 3: 个人计算机 (1981-)&quot;">​</a></h2><h3 id="_4-1-形态定义" tabindex="-1">4.1 形态定义 <a class="header-anchor" href="#_4-1-形态定义" aria-label="Permalink to &quot;4.1 形态定义&quot;">​</a></h3><ul><li>单台桌上机, 价格 $1000-5000, 1 人 1 机.</li><li><strong>IBM PC 开放架构</strong> (1981): IBM 只把 BIOS 留 copyright, 其它都让外面 chip 厂做; Compaq 等做 clean-room BIOS → PC clone 洪流 → x86 + DOS 标准.</li><li><strong>Wintel 联盟</strong> (Windows + Intel): 1990s 主导.</li></ul><h3 id="_4-2-操作系统迭代" tabindex="-1">4.2 操作系统迭代 <a class="header-anchor" href="#_4-2-操作系统迭代" aria-label="Permalink to &quot;4.2 操作系统迭代&quot;">​</a></h3><ul><li>MS-DOS 1.0 (1981) → 6.22 (1994).</li><li>Windows 1.0 (1985) → 3.x (1990-1993) → 95 / 98 (1995-1998) → NT / 2000 / XP / 7 / 10 / 11.</li><li>终于 Windows + Office 成为商业上标准应用.</li></ul><h3 id="_4-3-关键软件革命" tabindex="-1">4.3 关键软件革命 <a class="header-anchor" href="#_4-3-关键软件革命" aria-label="Permalink to &quot;4.3 关键软件革命&quot;">​</a></h3><ul><li>VisiCalc (1979 Apple II) 第一代 killer app; Lotus 1-2-3 → Excel 接力.</li><li>Internet 同期借助浏览器从科研拉到家里 (Mosaic → Navigator → IE → Firefox → Chrome).</li></ul><h3 id="_4-4-形态不变但内部-xpu-化" tabindex="-1">4.4 形态不变但内部 XPU 化 <a class="header-anchor" href="#_4-4-形态不变但内部-xpu-化" aria-label="Permalink to &quot;4.4 形态不变但内部 XPU 化&quot;">​</a></h3><ul><li>至 2024-2026, 校园 / 办公 PC 大多内含 NPU (Apple Neural Engine / 骁龙 Hexagon / Intel / AMD NPU); 传统桌面任务在 CPU, 视频处理在 GPU / NPU 媒体引擎, AI 推理在 NPU. 用户的&quot;键盘手&quot;完全感受不到分工, 但芯片任务被分配得像 Viking 时代分工一样精细.</li></ul><hr><h2 id="五、阶段-4-单片机与嵌入式-1976" tabindex="-1">五、阶段 4: 单片机与嵌入式 (1976-) <a class="header-anchor" href="#五、阶段-4-单片机与嵌入式-1976" aria-label="Permalink to &quot;五、阶段 4: 单片机与嵌入式 (1976-)&quot;">​</a></h2><h3 id="_5-1-8-bit-单片机史" tabindex="-1">5.1 8-bit 单片机史 <a class="header-anchor" href="#_5-1-8-bit-单片机史" aria-label="Permalink to &quot;5.1 8-bit 单片机史&quot;">​</a></h3><ul><li>Intel 8048 (1976)、8051 (1980) — 集成 CPU + RAM + ROM + IO 在一片, 既家电控制也打印机控制.</li><li>Microchip PIC, Atmel AVR — 90 年代起家电 / 工业占比大.</li><li>32-bit ARM Cortex-M (2004+) — 给嵌入式加上 MMU-less 32 位 → MCU 进入位数升级时代; 现代智能家居系列用 STM32 / nRF52 / ESP32.</li></ul><h3 id="_5-2-关键契约与约束" tabindex="-1">5.2 关键契约与约束 <a class="header-anchor" href="#_5-2-关键契约与约束" aria-label="Permalink to &quot;5.2 关键契约与约束&quot;">​</a></h3><ul><li>8/16-bit 单片机典型几十 MHz, 几 KB SRAM, 几十 KB Flash; 低功耗 (&lt; mA @ 3.3V) 比性能重要.</li><li>程序循环 + 中断驱动, 裸跑或 RTOS (FreeRTOS / Zephyr).</li><li>适配硬件 IO 与外设协议 (I2C / SPI / UART / CAN), 这是 [操作系统 + 编译原理] 的下边界实践.</li></ul><h3 id="_5-3-树莓派-嵌入式-linux-与新形态" tabindex="-1">5.3 树莓派 / 嵌入式 Linux 与新形态 <a class="header-anchor" href="#_5-3-树莓派-嵌入式-linux-与新形态" aria-label="Permalink to &quot;5.3 树莓派 / 嵌入式 Linux 与新形态&quot;">​</a></h3><ul><li>Raspberry Pi (2012 起) = ARM 单片机 + Linux; 普通人可以 35 美元跑完整 OS + python.</li><li>BeagleBone Black / Jetson Nano / Coral Dev Board — 边缘 AI 推理板, AI 工业应用入门.</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>单片机不像服务器: 没虚拟内存、没 OS 保护、通常没 fork、可能没浮点单元、int 大小因编译器变. 把 X86 心智照搬过去会出错—这就是为什么 MCU 章节经常与&quot;嵌入式 C&quot;配套教.</p></div><h3 id="_5-4-物联网-iot-与-micro-cloud-端" tabindex="-1">5.4 物联网 (IoT) 与 MICRO-CLOUD 端 <a class="header-anchor" href="#_5-4-物联网-iot-与-micro-cloud-端" aria-label="Permalink to &quot;5.4 物联网 (IoT) 与 MICRO-CLOUD 端&quot;">​</a></h3><ul><li>IoT 设备峰值数十亿台 ↔ 几十亿 IP; 6LoWPAN / MQTT / CoAP / OPC UA 等协议.</li><li>数据汇总到边缘网关 → 上云 / 流式 → ML 推理再下沉到端 (端 NPU) 的&quot;edge ML&quot; 链路成主流.</li></ul><hr><h2 id="六、阶段-5-arm-移动-2007" tabindex="-1">六、阶段 5: ARM + 移动 (2007-) <a class="header-anchor" href="#六、阶段-5-arm-移动-2007" aria-label="Permalink to &quot;六、阶段 5: ARM + 移动 (2007-)&quot;">​</a></h2><h3 id="_6-1-arm-历史" tabindex="-1">6.1 ARM 历史 <a class="header-anchor" href="#_6-1-arm-历史" aria-label="Permalink to &quot;6.1 ARM 历史&quot;">​</a></h3><ul><li><strong>Acorn Archimedes + ARM1</strong> (1985): Acorn Computers 设计的低功耗 32-bit RISC CPU.</li><li><strong>ARM (公司) 1990 独立</strong>, 商业模式 = <strong>ISA 授权 + 核授权</strong>: 谁都拿 ARM 设计 → Apple A 系列 / Snapdragon /Samsung Exynos / 联发科 Dimensity / 华为麒麟 / Google Tensor; 都按 ARM 几亿片付版税.</li><li><strong>ARM 在 2007 iPhone 起进入手机主流</strong>, 2010 iPad, 2020 Apple M1 桌面 / 笔记本, 2018 AWS Graviton 进数据中心, 2023 通 Microsoft Windows on ARM, 2024+ 自研车规级芯片 (Tesla / 高通 8295 / 联发科).</li></ul><h3 id="_6-2-risc-与-cisc-的胜负史" tabindex="-1">6.2 RISC 与 CISC 的胜负史 <a class="header-anchor" href="#_6-2-risc-与-cisc-的胜负史" aria-label="Permalink to &quot;6.2 RISC 与 CISC 的胜负史&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1980 x86 CISC 起 ← IBM PC 路线</span></span>
<span class="line"><span>1985 ARM1 RISC</span></span>
<span class="line"><span>1990 RISC 工作站死 (Sun/SGI 让位 PC)</span></span>
<span class="line"><span>2000 x86 由摩尔推往更快</span></span>
<span class="line"><span>2005 单核停 → x86 强向多核, 但功耗不行入手机</span></span>
<span class="line"><span>2007 iPhone ARM</span></span>
<span class="line"><span>2010 ARM Cortex-A 系打平 x86 性能/瓦</span></span>
<span class="line"><span>2020 Apple M1 在桌面都胜 x86</span></span>
<span class="line"><span>2024+ ARM 的 Neoverse V/N 与自研 (Graviton / XuanTie / 阿里 倚天)成型成为数据中心升</span></span></code></pre></div><p><strong>关键</strong>: RISC 并未在 1990 年工作站时代赢; 它是在 <strong>mobile / 功耗 / 集成 SoC</strong> 这一新形态上 2007+ 赢, 再逆向卷回桌面与数据中心.</p><h3 id="_6-3-形态新约-app-触屏-推送" tabindex="-1">6.3 形态新约: App + 触屏 + 推送 <a class="header-anchor" href="#_6-3-形态新约-app-触屏-推送" aria-label="Permalink to &quot;6.3 形态新约: App + 触屏 + 推送&quot;">​</a></h3><ul><li>用户在触摸屏上手势/语音交互; 通知 / 推送代替弹窗; 后台 / 前台切换由 OS 自动; 电池结构作为合约 (energy budget per app).</li><li>操作系统 iOS / Android 主流, <strong>沙箱 + 审核制 + 应用商店分发</strong> 与 PC 时代相比完全变了软件商业模式.</li><li>API 重心从 Linux 系统调用移到 Apple SDK / Android SDK; JNI/Swift/Flutter/React Native 跨平台层多样.</li></ul><h3 id="_6-4-arm-在-2024-2026-的姿态" tabindex="-1">6.4 ARM 在 2024-2026 的姿态 <a class="header-anchor" href="#_6-4-arm-在-2024-2026-的姿态" aria-label="Permalink to &quot;6.4 ARM 在 2024-2026 的姿态&quot;">​</a></h3><ul><li>ARMv9 + SVE2 与 CXL / 一致性 / page table 多机架化扩展 (CCIX → CXL 4.0) 进一步强化数据中心能力.</li><li>Apple M5 / 骁龙 X2 Elite / Nvidia Grace — 桌面 / PC / 服务器 ARM 都路线成熟; x86 走异构 + chiplet + AI 加速的 binary compatibility.</li><li>中国: 阿里平头哥 倚天 / 华为 昇腾 CPU + 鲲鹏 / 飞腾 / 龙芯 / 海光 — 在政企 / 信创 / 金融大批量部署.</li></ul><hr><h2 id="七、阶段-6-web-与云计算-1995" tabindex="-1">七、阶段 6: Web 与云计算 (1995-) <a class="header-anchor" href="#七、阶段-6-web-与云计算-1995" aria-label="Permalink to &quot;七、阶段 6: Web 与云计算 (1995-)&quot;">​</a></h2><h3 id="_7-1-web-1-0-→-2-0-→-3-x" tabindex="-1">7.1 Web 1.0 → 2.0 → 3.x <a class="header-anchor" href="#_7-1-web-1-0-→-2-0-→-3-x" aria-label="Permalink to &quot;7.1 Web 1.0 → 2.0 → 3.x&quot;">​</a></h3><ul><li><strong>Web 1.0</strong> (1991-2004): 静态 HTML + 链接 + 邮件; 浏览器看网页.</li><li><strong>Web 2.0</strong> (2004-): AJAX + UGC (User Generated Content); Wikipedia / YouTube / Facebook / Twitter 起势; JavaScript + CSS + DOM 成熟框架 (jQuery → React → Vue / Angular).</li><li><strong>Web 3.0</strong> (2014-): Blockchain + decentralized identity + 媒介原资产, 部分 industrial deployment 但仍是 experimental.</li><li><strong>Web 与 LLM 时代</strong> (2023-): 浏览器内嵌 LLM (Edge Copilot / Brave Leo), Browser-LLM 协议 (MCP, etc).</li></ul><h3 id="_7-2-云原生态" tabindex="-1">7.2 云原生态 <a class="header-anchor" href="#_7-2-云原生态" aria-label="Permalink to &quot;7.2 云原生态&quot;">​</a></h3><ul><li><strong>AWS EC2</strong> (2006) 起, 一切 on-demand; <strong>S3</strong> 对象存储; <strong>RDS</strong> 一键数据库. 资本支出从机房 → &quot;API 一个 form&quot;.</li><li>容器化 (Docker 2013), Kubernetes (2014-2018), service mesh, GitOps, IaC (Terraform / Pulumi / Crossplane).</li><li>&quot;无服务器 (serverless)&quot;: Lambda / FaaS / EventBridge — 上层抽象更上一层, 工程师不接触实例.</li><li>2024+ 通 WebGPU / WebGPU compute API / WebAssembly 系统接口 (WASI) 让浏览器执行本地任务 (含 LLM 推理).</li></ul><h3 id="_7-3-数据中心-机房是社会" tabindex="-1">7.3 数据中心 &quot;机房是社会&quot; <a class="header-anchor" href="#_7-3-数据中心-机房是社会" aria-label="Permalink to &quot;7.3 数据中心 &quot;机房是社会&quot;&quot;">​</a></h3><p>云数据中心 (Google / AWS / Azure / 阿里 / meta / 字节 / 腾讯) 一般 10-100MW+, 需 50-100MW 风电 / 水电 / 核电配套. 在 2023+ AI 训练需求暴增, 单数据中心能力推到 1GW+ 接边; 核电 / SMR (small modular reactor) 直接进 Microsoft / Amazon 长约; 数据中心从&quot;工程师资产&quot;变&quot;国家级能源政策&quot;, 是不可忽略的形态变化.</p><hr><h2 id="八、阶段-7-ai-xpu-异构时代-2012" tabindex="-1">八、阶段 7: AI / XPU 异构时代 (2012-) <a class="header-anchor" href="#八、阶段-7-ai-xpu-异构时代-2012" aria-label="Permalink to &quot;八、阶段 7: AI / XPU 异构时代 (2012-)&quot;">​</a></h2><h3 id="_8-1-xpu-谱系" tabindex="-1">8.1 XPU 谱系 <a class="header-anchor" href="#_8-1-xpu-谱系" aria-label="Permalink to &quot;8.1 XPU 谱系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类</th><th>用途</th><th>当前主流 (2024-2026)</th></tr></thead><tbody><tr><td><strong>CPU</strong></td><td>控制流 + 低并发</td><td>x86, ARM, RISC-V, Power</td></tr><tr><td><strong>GPU</strong></td><td>大并行张量</td><td>NVIDIA H100/H200/B200/GB200, AMD MI300/MI450, Intel Arc/Battlemage/Jaguar Shores</td></tr><tr><td><strong>TPU</strong></td><td>张量 ASIC</td><td>Google TPU v5p/v6 Trillium</td></tr><tr><td><strong>NPU</strong></td><td>端侧 AI 推理</td><td>Apple Neural Engine, 骁龙 Hexagon, MediaTek APU, Intel / AMD NPU, 华为 Ascend NPU</td></tr><tr><td><strong>DPU / IPU</strong></td><td>网络与存储 off-load</td><td>NVIDIA Bluefield-3, Fungible / Pensando / 阿里 CIPU</td></tr><tr><td><strong>FPGA</strong></td><td>可重配 / 小批量</td><td>Xilinx Versal / Intel Agilex / 国产</td></tr><tr><td><strong>ASIC</strong></td><td>固定 workload</td><td>Groq LPU, Cerebras WSE-3 / SambaNova SN40L / Tenstorrent</td></tr><tr><td><strong>RAID / SmartNIC</strong></td><td>OS bypass</td><td>Broadcom Memory, Marvell, NVIDIA BlueField</td></tr><tr><td><strong>量子</strong></td><td>特定子问题模拟</td><td>IBM / Google / IonQ / Quantinuum / 国盾量子 / 本源量子</td></tr></tbody></table><h3 id="_8-2-为什么-xpu-必然" tabindex="-1">8.2 为什么 XPU 必然 <a class="header-anchor" href="#_8-2-为什么-xpu-必然" aria-label="Permalink to &quot;8.2 为什么 XPU 必然&quot;">​</a></h3><ul><li>Dennard scaling 2005 止 → 单核不再提速 → 必须 SIMD / 多核 / 加速器.</li><li>AI 训练 = 矩阵 × 矩阵 (GEMM) 大规模并发, CPU SIMD 的乱序调度远不如 GPU 的 SIMT.</li><li>推理 latency / 功耗关键, NPU 在 50-200 GOPS/W 比通用 CPU 5-10x 能效.</li><li>摩尔放缓 → 工程师换 vertical specialization: 每类算力做专门芯片 → 形成多 die + 互联 (NVLink 5/6 / CXL 3.x / UALink / Infinity Fabric).</li></ul><h3 id="_8-3-互联-interconnect-与-memory-hierarchy-重塑" tabindex="-1">8.3 互联 (interconnect) 与 memory hierarchy 重塑 <a class="header-anchor" href="#_8-3-互联-interconnect-与-memory-hierarchy-重塑" aria-label="Permalink to &quot;8.3 互联 (interconnect) 与 memory hierarchy 重塑&quot;">​</a></h3><ul><li>关键事实: 2024-2026 大模型训练, <strong>算力不卡 GPU 而卡 GPU 间带宽 + HBM 容量</strong>.</li><li>HBM4 + CXL 3.x + NVLink 5/6 / Infinity Fabric 让&quot;memory pool&quot; 成为单数据中心级资源.</li><li><strong>背景</strong>: 见 <a href="./../computer-arch/interconnects">第八部分 / interconnects</a> 与 <a href="./../computer-arch/memory-hierarchy">memory-hierarchy</a>.</li></ul><h3 id="_8-4-xpu-上的-用户-是谁" tabindex="-1">8.4 XPU 上的&quot;用户&quot; 是谁 <a class="header-anchor" href="#_8-4-xpu-上的-用户-是谁" aria-label="Permalink to &quot;8.4 XPU 上的&quot;用户&quot; 是谁&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类</th><th>用户群</th></tr></thead><tbody><tr><td>CPU</td><td>99% 程序员 (Linux, Python, Docker, ...)</td></tr><tr><td>GPU</td><td>ML 工程师 / 科研 / cinema render</td></tr><tr><td>TPU / 推理 ASIC</td><td>Google 内部 + Google Cloud 用户</td></tr><tr><td>NPU</td><td>几乎人人 (端 AI), 但不暴露编程接口</td></tr><tr><td>DPU</td><td>云厂商内部 + Smart NIC 工程师</td></tr><tr><td>FPGA</td><td>通信 / 金融高频 / 数据center 部分</td></tr><tr><td>量子</td><td>科研组与少量 crypto 实验室</td></tr></tbody></table><p><strong>统一框架</strong>: MLIR / OpenXLA / TorchTitan / SDAA — 让你写一份 PyTorch 在哪一 XPU 上都跑, 内部 dispatcher 把算子路由到对应芯片.</p><hr><h2 id="九、形态演进对工程师的影响" tabindex="-1">九、形态演进对工程师的影响 <a class="header-anchor" href="#九、形态演进对工程师的影响" aria-label="Permalink to &quot;九、形态演进对工程师的影响&quot;">​</a></h2><h3 id="_9-1-工程师-脑模型-演化" tabindex="-1">9.1 工程师&quot;脑模型&quot; 演化 <a class="header-anchor" href="#_9-1-工程师-脑模型-演化" aria-label="Permalink to &quot;9.1 工程师&quot;脑模型&quot; 演化&quot;">​</a></h3><ul><li>1960 大型机时代: 排队作业 / 数据表 / 作业流 / COBOL 主导.</li><li>1980 PC 时代: 单人作业 / 文件 / GUI 桌面 / C / VB.</li><li>2000 Web 时代: client-server / DB / HTTP / PHP / Java Servlet / Spring.</li><li>2010 移动时代: app / 推送 / 通知 / 离线 cache / Swift / Kotlin / Flutter.</li><li>2020 云时代: container / K8s / IaC / GitOps / observability / micro-service.</li><li>2025 AI/Agent 时代: prompt + tool use + MCP + sub-agent orchestrator + model registry.</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>这不是替代关系, 是<strong>叠加</strong>: 现在大型机仍有 / 单片机仍有 / PC 仍有 / 移动仍有 / 云 / AI 都仍是. 一个新的&quot;全栈工程师&quot;必须能在层之间切换语义, 不要总停留在写 web 后端的脑模型里.</p></div><h3 id="_9-2-形态与抽象层级的双重图" tabindex="-1">9.2 形态与抽象层级的双重图 <a class="header-anchor" href="#_9-2-形态与抽象层级的双重图" aria-label="Permalink to &quot;9.2 形态与抽象层级的双重图&quot;">​</a></h3><p>把 <a href="./abstraction-layers">abstraction-layers</a> 的 10 层叠加在这 7 段形态上, 每段形态都激活某些层:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>形态              主要激活的抽象层级</span></span>
<span class="line"><span>─────────────────────────────────</span></span>
<span class="line"><span>Mainframe          1-7 (低层缺独立硬件锤)</span></span>
<span class="line"><span>Mini               3-7 (Unix 起来)</span></span>
<span class="line"><span>PC                 1-8 (高级语言运行时大众化)</span></span>
<span class="line"><span>MCU                1-5 (baremetal 与 ISA 露骨)</span></span>
<span class="line"><span>Mobile             1-9 (系统 → App → 触屏)</span></span>
<span class="line"><span>Cloud / Web        1-9 (容器 + 微服务 + 网络套接)</span></span>
<span class="line"><span>AI / XPU           1-10 (新增 LLM 层; 每层都革新)</span></span></code></pre></div><p>→ 这就是为什么 AI 时代让人&quot;压力大&quot;: 同时在 10 层里推 — 数学层 (第零部分) / 硬件层 (第八部分) / OS (第二部分) / 编译 (第五部分) / AI (第十二部分) 全被推.</p><h3 id="_9-3-工程师必备的-形态切换-能力" tabindex="-1">9.3 工程师必备的&quot;形态切换&quot; 能力 <a class="header-anchor" href="#_9-3-工程师必备的-形态切换-能力" aria-label="Permalink to &quot;9.3 工程师必备的&quot;形态切换&quot; 能力&quot;">​</a></h3><ol><li>给我一段 CUDA kernel, 能定位它在第 3 (RTL) / 4 (microarch SM) / 5 (ISA) / 9 (PyTorch→ cuBLAS path).</li><li>给我一段 Go 服务, 能告诉我它的 latency 受第 6 (kernel fork) / 第 7 (epoll) / 第 4 (cache miss) 哪层主导.</li><li>给我一段 Transformer 训练脚本, 能告诉我它在 XPU 谱: CPU 做控制, GPU 做 GEMM, DPU/NIC 做梯度同步, HBM 做激活 cache.</li></ol><hr><h2 id="十、未来-2026-应看的形态信号" tabindex="-1">十、未来 (2026+) 应看的形态信号 <a class="header-anchor" href="#十、未来-2026-应看的形态信号" aria-label="Permalink to &quot;十、未来 (2026+) 应看的形态信号&quot;">​</a></h2><ul><li><strong>NPU 进 PC / 移动成主流</strong>: Apple Intelligence / Windows Copilot+ / Android AI 主推.</li><li><strong>CXL pool 化内存</strong>: 数据中心级 &quot;memory pool&quot; 走出研究阶段, 进入商用 workload.</li><li><strong>量子-经典混合协处理</strong> (QPU-as-accelerator for crypto / material / optimization): 部分 HPC workload 上线.</li><li><strong>Chiplet + die-stacking</strong>: AMD 3D V-Cache / Intel Foveros / 台积电 CoWoS / chiplet 互联取代单大 die.</li><li><strong>6G 与低轨卫星直连</strong>: 卫星互联网补齐地球 IP (Starlink 等).</li><li><strong>AI 编程范式入工程主体</strong>: Agent / MCP / multi-tool loop 成为默认开发栈, IDE 与 git 都换头脑.</li></ul><hr><h2 id="十一、与后续各部分的接口" tabindex="-1">十一、与后续各部分的接口 <a class="header-anchor" href="#十一、与后续各部分的接口" aria-label="Permalink to &quot;十一、与后续各部分的接口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>形态</th><th>对应后续部分</th></tr></thead><tbody><tr><td>Mainframe / Mini</td><td>第二部分 OS 历史; 第五部分编译器历史</td></tr><tr><td>PC</td><td>第八部分组成原理 (CPU 流水线 / cache / ISA)</td></tr><tr><td>MCU / 嵌入式</td><td>第二部分 OS 至深 (RTOS / eBPF 系统级调度)</td></tr><tr><td>Mobile / ARM</td><td>第八部分 ISA (x86/ARM/RISC-V 横向纵向)</td></tr><tr><td>Cloud / Web</td><td>第三部分网络 + 第六部分分布式 + 第七部分系统设计</td></tr><tr><td>AI / XPU</td><td>第八部分 GPU/TPU + 第十二部分 AI/ML</td></tr></tbody></table><hr><h2 id="十二、结束-速查表" tabindex="-1">十二、结束 + 速查表 <a class="header-anchor" href="#十二、结束-速查表" aria-label="Permalink to &quot;十二、结束 + 速查表&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>一页快速唤回:</p><ul><li><strong>七段形态</strong>: 大型机 → 小型机 → PC → MCU → 移动/ARM → 云/Web → AI/XPU.</li><li>每段不是替代: 是叠加; 在 2026 全部共存.</li><li>各段对应&quot;新用户群 + 新软件范式 + 新契约 + 新主流芯片&quot;.</li><li>ARM 经手机 wtt2007 反袭 + 2020 Apple Silicon 卷回桌面 + 2018 Graviton 卷入数据器.</li><li>XPU 不是 CPU 替代, 是分工 = 控制流 CPU / 张量 GPU / 服务 off-load DPU / 端 AI NPU / 推理 ASIC.</li><li>形态与抽象层级多对多: 形态演进激活抽象层级某些段.</li><li>工程师能力核心: 给一份新名词 (MEC / AI PC / agentic workload / ...) 能定位在形态 + 抽象层级哪一格.</li></ul></div><hr><p>下一篇: <a href="./standing-on-shoulders">4. 主干纵贯: CPU/内存 → OS/Linux → 网络/Web → DB → 编译 → 分布式 → AI 的承接链</a>.</p>`,101)])])}const P=a(r,[["render",n]]);export{c as __pageData,P as default};
